        n = len(cnf[0])
        V = [[0] * (2**n) for _ in range(n)]
        for i in range(n):
            for j in range(1 << n):
                if bin(j).count('1') % 2 == 0:
                    V[i][j] = 1
                else:
                    V[i][j] = -1
        return sum(sum(V[i][j] * V[i][k] for k in range(1 << n)) for i in range(n)) / (n * (2**n))

    def boolean_circuit_entropy(cnf):
        n = len(cnf[0])
        transitions = {}
        for clause in cnf:
            for j in range(1 << n):
                if all(x in bin(j) for x in clause):
                    for k in range(1 << n):
                        if any(x not in bin(k) for x in clause):
                            if (j, clause[0]) not in transitions:
                                transitions[(j, clause[0])] = []
                            transitions[(j, clause[0])].append(k)
        entropy = 0
        for j in range(1 << n):
            total = sum(len(transitions.get((j, x), [])) for x in set(cnf))
            for k in range(1 << n):
                if (j, cnf[0][0]) in transitions:
                    p = len([x for x in transitions[(j, cnf[0][0])] if bin(k) == x])
                    entropy -= p * math.log2(p / total)
        return entropy

    n = random.randint(5, 40)
